import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getLatestMovies } from '../api/tmdb';

function MovieDetail() {
  const { id } = useParams();
  const [movie, setMovie] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchMovieDetail = async () => {
      setLoading(true);
      const movies = await getLatestMovies();
      const found = movies.find((m) => String(m.id) === String(id)) || movies[0];
      setMovie(found);
      setLoading(false);
    };
    fetchMovieDetail();
  }, [id]);

  if (loading) {
    return (
      <div className="w-full min-h-screen bg-[#0b090e] flex items-center justify-center text-white" style={{ fontFamily: 'Pretendard, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', WebkitFontSmoothing: 'antialiased' }}>
        <p className="text-sm font-bold animate-pulse text-[#503396]">영화 정보를 불러오는 중...</p>
      </div>
    );
  }

  const posterUrl = movie?.poster_path 
    ? `https://image.tmdb.org/t/p/w500${movie.poster_path}` 
    : "https://via.placeholder.com/300x450?text=No+Image";

  return (
    <div className="w-full min-h-screen bg-[#0b090e] text-white pb-24" style={{ fontFamily: 'Pretendard, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif', WebkitFontSmoothing: 'antialiased' }}>
      
      {/* 상단 타이틀 영역 */}
      <div className="max-w-5xl mx-auto px-6 pt-10">
        <h2 className="text-3xl font-black tracking-tight text-white mb-2">{movie?.title}</h2>
        <div className="flex items-center gap-3 text-xs text-zinc-400">
          <span>2026 &bull; 15+ &bull; 18 Episodes &bull; Language: KO</span>
        </div>
        <div className="flex gap-2 mt-4">
          <span className="px-3 py-1 rounded-full bg-zinc-800 border border-white/10 text-xs font-bold text-zinc-300">Mystery</span>
          <span className="px-3 py-1 rounded-full bg-zinc-800 border border-white/10 text-xs font-bold text-zinc-300">Thriller</span>
          <span className="px-3 py-1 rounded-full bg-zinc-800 border border-white/10 text-xs font-bold text-zinc-300">Suspense</span>
        </div>
      </div>

      {/* 중단 통계 바 영역 */}
      <div className="max-w-5xl mx-auto px-6 mt-8">
        <div className="bg-zinc-900/80 border border-white/10 rounded-2xl p-6 shadow-sm flex items-center justify-around text-center">
          <div>
            <span className="text-xs text-zinc-400 block mb-1">실관람 평점</span>
            <span className="text-xl font-black text-[#503396]">M 9.5</span>
          </div>
          <div className="border-l border-white/10 h-10"></div>
          <div>
            <span className="text-xs text-zinc-400 block mb-1">예매율</span>
            <span className="text-xl font-black text-white">1위 <span className="text-xs font-normal text-zinc-400">(21.4%)</span></span>
          </div>
          <div className="border-l border-white/10 h-10"></div>
          <div>
            <span className="text-xs text-zinc-400 block mb-1">누적관객수</span>
            <span className="text-xl font-black text-white">6,696,818 명</span>
          </div>
        </div>
      </div>

      {/* 포스터 및 상세 정보 영역 */}
      <div className="max-w-5xl mx-auto px-6 mt-8">
        <div className="flex flex-col md:flex-row gap-8">
          
          {/* 포스터 */}
          <div className="w-full md:w-80 flex-shrink-0">
            <div className="rounded-2xl overflow-hidden shadow-lg border border-white/10">
              <img src={posterUrl} alt={movie?.title} className="w-full h-auto object-cover block" />
            </div>
          </div>

          {/* 텍스트 정보 (감독, 출연진, 줄거리) */}
          <div className="flex flex-col justify-between flex-grow space-y-6 bg-zinc-900/50 border border-white/10 rounded-2xl p-6">
            <div className="space-y-4 text-xs text-zinc-300">
              
              <div>
                <strong className="text-zinc-400 block mb-1">등장인물:</strong>
                <p className="text-white font-medium">{movie?.cast || '정보 없음'}</p>
              </div>

              <div>
                <strong className="text-zinc-400 block mb-1">감독:</strong>
                <p className="text-white font-medium">{movie?.director || '정보 없음'}</p>
              </div>

              <div className="pt-2 border-t border-white/10">
                <strong className="text-zinc-400 block mb-1">줄거리:</strong>
                <p className="text-zinc-300 leading-relaxed font-medium">
                  {movie?.overview || '등록된 줄거리가 없습니다.'}
                </p>
              </div>

            </div>

            {/* 예매하기 버튼 */}
            <div>
              <button 
                onClick={() => navigate('/schedule')}
                className="w-full py-3.5 bg-[#503396] hover:bg-[#432a7e] text-white rounded-xl text-xs font-black transition shadow-md"
              >
                상영시간표 및 예매하기
              </button>
            </div>
          </div>

        </div>
      </div>

    </div>
  );
}

export default MovieDetail;
